[Expected Approach] Multiply the Required Terms Directly - O(r) Time and O(1) SpaceInstead of computing n! and (n-r)! separately, use the relation: nPr = n × (n - 1) × (n - 2) × ... × (n - r + 1). This computes only the required r terms, avoiding unnecessary factorial calculations and making the solution more efficient.
            C++

    #include <iostream>
using namespace std;

long long nPr(int n, int r)
{
    if (r > n)
        return 0;

    long long ans = 1;

    // Compute n × (n-1) × ... × (n-r+1)
    for (int i = 0; i < r; i++)
        ans *= (n - i);

    return ans;
}

int main()
{
    int n = 5;
    int r = 2;

    cout << nPr(n, r) << endl;

    return 0;
}


